CREATE TABLE IF NOT EXISTS "user" (id text PRIMARY KEY,name text NOT NULL,email text UNIQUE NOT NULL,"emailVerified" boolean NOT NULL DEFAULT false,image text,role text NOT NULL DEFAULT 'user' CHECK(role IN ('user','admin')),deleted_at timestamptz,"createdAt" timestamptz NOT NULL DEFAULT now(),"updatedAt" timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS "session" (id text PRIMARY KEY,"expiresAt" timestamptz NOT NULL,token text UNIQUE NOT NULL,"createdAt" timestamptz NOT NULL DEFAULT now(),"updatedAt" timestamptz NOT NULL DEFAULT now(),"ipAddress" text,"userAgent" text,"userId" text NOT NULL REFERENCES "user"(id) ON DELETE CASCADE);
CREATE INDEX IF NOT EXISTS session_user_idx ON "session"("userId");
CREATE TABLE IF NOT EXISTS account (id text PRIMARY KEY,"accountId" text NOT NULL,"providerId" text NOT NULL,"userId" text NOT NULL REFERENCES "user"(id) ON DELETE CASCADE,"accessToken" text,"refreshToken" text,"idToken" text,"accessTokenExpiresAt" timestamptz,"refreshTokenExpiresAt" timestamptz,scope text,password text,"createdAt" timestamptz NOT NULL DEFAULT now(),"updatedAt" timestamptz NOT NULL DEFAULT now(),UNIQUE("providerId","accountId"));
CREATE TABLE IF NOT EXISTS verification (id text PRIMARY KEY,identifier text NOT NULL,value text NOT NULL,"expiresAt" timestamptz NOT NULL,"createdAt" timestamptz NOT NULL DEFAULT now(),"updatedAt" timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS verification_identifier_idx ON verification(identifier);
CREATE TABLE IF NOT EXISTS neighborhoods (id text PRIMARY KEY,name text NOT NULL,start_seat int NOT NULL,end_seat int NOT NULL,color text NOT NULL,CHECK(start_seat>=1 AND end_seat<=10000 AND start_seat<=end_seat));
CREATE TABLE IF NOT EXISTS orders (id text PRIMARY KEY,user_id text NOT NULL REFERENCES "user"(id),package_id text NOT NULL,amount int NOT NULL CHECK(amount>=0),currency text NOT NULL DEFAULT 'usd',status text NOT NULL CHECK(status IN ('checkout_pending','processing','paid','failed','expired','refund_requested','refunded','disputed','fulfillment_issue')),provider text NOT NULL CHECK(provider IN ('stripe','development','seed')),checkout_session_id text UNIQUE,checkout_expires_at timestamptz,payment_intent_id text UNIQUE,profile_draft jsonb NOT NULL,is_demo boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS orders_user_idx ON orders(user_id,created_at DESC);
CREATE TABLE IF NOT EXISTS reservations (id text PRIMARY KEY,user_id text NOT NULL REFERENCES "user"(id),order_id text REFERENCES orders(id),kind text NOT NULL CHECK(kind IN ('checkout','invitation')),status text NOT NULL CHECK(status IN ('active','converted','released')),expires_at timestamptz NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS seats (id int PRIMARY KEY CHECK(id BETWEEN 1 AND 10000),neighborhood_id text NOT NULL REFERENCES neighborhoods(id),state text NOT NULL DEFAULT 'available' CHECK(state IN ('available','invitation_held','checkout_held','payment_processing','purchased','unavailable')),owner_id text REFERENCES "user"(id),order_id text REFERENCES orders(id),reservation_id text REFERENCES reservations(id),hold_expires_at timestamptz,updated_at timestamptz NOT NULL DEFAULT now(),CHECK((state='purchased' AND owner_id IS NOT NULL AND order_id IS NOT NULL) OR state<>'purchased'));
CREATE INDEX IF NOT EXISTS seats_neighborhood_idx ON seats(neighborhood_id,id);
CREATE INDEX IF NOT EXISTS seats_state_idx ON seats(state,id);
CREATE TABLE IF NOT EXISTS order_items (order_id text NOT NULL REFERENCES orders(id),seat_id int NOT NULL REFERENCES seats(id),PRIMARY KEY(order_id,seat_id));
CREATE TABLE IF NOT EXISTS profiles (seat_id int PRIMARY KEY REFERENCES seats(id),display_name text NOT NULL CHECK(char_length(display_name) BETWEEN 1 AND 30),message text NOT NULL CHECK(char_length(message)<=140),dish text NOT NULL,customization jsonb NOT NULL,link text CHECK(link IS NULL OR link ~ '^https?://'),visibility text NOT NULL DEFAULT 'pending' CHECK(visibility IN ('pending','published','hidden','private')),reactions_enabled boolean NOT NULL DEFAULT true,is_demo boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS profiles_visibility_idx ON profiles(visibility,seat_id);
CREATE TABLE IF NOT EXISTS invitations (id text PRIMARY KEY,token_hash text UNIQUE NOT NULL,type text NOT NULL CHECK(type IN ('courtesy','paid')),source_seat_id int NOT NULL REFERENCES seats(id),target_seat_id int NOT NULL REFERENCES seats(id),owner_id text NOT NULL REFERENCES "user"(id),status text NOT NULL CHECK(status IN ('active','claimed','revoked','expired')),expires_at timestamptz NOT NULL,claimed_by text REFERENCES "user"(id),created_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX IF NOT EXISTS invitation_one_active_source_idx ON invitations(source_seat_id) WHERE status='active' AND type='courtesy';
CREATE UNIQUE INDEX IF NOT EXISTS invitation_one_active_target_idx ON invitations(target_seat_id) WHERE status='active';
CREATE TABLE IF NOT EXISTS reactions (id text PRIMARY KEY,seat_id int NOT NULL REFERENCES seats(id),actor_hash text NOT NULL,idempotency_key text UNIQUE NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS reactions_actor_idx ON reactions(actor_hash,created_at);
CREATE INDEX IF NOT EXISTS reactions_seat_idx ON reactions(seat_id);
CREATE TABLE IF NOT EXISTS reports (id text PRIMARY KEY,seat_id int NOT NULL REFERENCES seats(id),actor_hash text NOT NULL,reason text NOT NULL CHECK(char_length(reason) BETWEEN 3 AND 1000),status text NOT NULL DEFAULT 'open' CHECK(status IN ('open','resolved')),created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS reports_open_idx ON reports(status,created_at DESC);
CREATE TABLE IF NOT EXISTS moderation_decisions (id text PRIMARY KEY,seat_id int NOT NULL REFERENCES seats(id),admin_id text NOT NULL REFERENCES "user"(id),action text NOT NULL,reason text,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS payment_events (id text PRIMARY KEY,type text NOT NULL,order_id text REFERENCES orders(id),outcome text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS audit_events (id text PRIMARY KEY,actor_id text REFERENCES "user"(id),action text NOT NULL,target text NOT NULL,details jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS audit_created_idx ON audit_events(created_at DESC);
CREATE TABLE IF NOT EXISTS support_issues (id text PRIMARY KEY,user_id text REFERENCES "user"(id),order_id text REFERENCES orders(id),kind text NOT NULL,message text NOT NULL,status text NOT NULL DEFAULT 'open' CHECK(status IN ('open','resolved')),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS settings (key text PRIMARY KEY,value jsonb NOT NULL,updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS development_outbox (id text PRIMARY KEY,email text NOT NULL,url text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
